import{c as a,Q as t,j as o,m as d}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Claude Code W26–W27 新功能（v2.1.185–v2.1.201）","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/42-w26-27-features.md","filePath":"research/best-practices/42-w26-27-features.md","lastUpdated":1785909234000}'),i={name:"research/best-practices/42-w26-27-features.md"};function l(r,e,s,n,c,h){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-code-w26–w27-新功能-v2-1-185–v2-1-201" tabindex="-1">Claude Code W26–W27 新功能（v2.1.185–v2.1.201） <a class="header-anchor" href="#claude-code-w26–w27-新功能-v2-1-185–v2-1-201" aria-label="Permalink to &quot;Claude Code W26–W27 新功能（v2.1.185–v2.1.201）&quot;">​</a></h1><blockquote><p><strong>Source:</strong> <a href="https://code.claude.com/docs/en/changelog" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/changelog</a><strong>Date Range:</strong> 2026-06-20 ~ 2026-07-03 <strong>Versions:</strong> v2.1.185 / v2.1.186 / v2.1.187 / v2.1.190 / v2.1.191 / v2.1.193 / v2.1.195 / v2.1.196 / v2.1.197 / v2.1.198 / v2.1.199 / v2.1.200 / v2.1.201</p></blockquote><blockquote><p>Claude Sonnet 5 本身另立 <code>41-claude-sonnet-5.md</code> 專篇；本檔僅記錄該版本（v2.1.197）在 Claude Code 內的整合細節。</p></blockquote><hr><h2 id="v2-1-185-2026-06-20-trivial" tabindex="-1">v2.1.185（2026-06-20，trivial） <a class="header-anchor" href="#v2-1-185-2026-06-20-trivial" aria-label="Permalink to &quot;v2.1.185（2026-06-20，trivial）&quot;">​</a></h2><p>串流中斷提示文字與觸發時機調整：「Waiting for API response · will retry in …」（原「No response from API · Retrying in …」），觸發門檻從 10 秒延長為 <strong>20 秒</strong>無回應。</p><hr><h2 id="v2-1-186-2026-06-22-feature-dense" tabindex="-1">v2.1.186（2026-06-22，feature-dense） <a class="header-anchor" href="#v2-1-186-2026-06-22-feature-dense" aria-label="Permalink to &quot;v2.1.186（2026-06-22，feature-dense）&quot;">​</a></h2><h3 id="cli-mcp-登入-登出" tabindex="-1">CLI MCP 登入/登出 <a class="header-anchor" href="#cli-mcp-登入-登出" aria-label="Permalink to &quot;CLI MCP 登入/登出&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>不需開 <code>/mcp</code> 選單即可完成 MCP 認證；<code>--no-browser</code> 支援 SSH 場景的 stdin redirect 流程。</p><h3 id="其他新增" tabindex="-1">其他新增 <a class="header-anchor" href="#其他新增" aria-label="Permalink to &quot;其他新增&quot;">​</a></h3><ul><li><code>/workflows</code> agent detail view 支援狀態篩選（按 <code>f</code>）</li><li><code>/plugin</code> Installed tab 新增「Skills」區塊</li><li><code>teammateMode: &quot;iterm2&quot;</code> 設定（缺少 <code>it2</code> CLI 會警告）</li></ul><h3 id="行為變更-需注意" tabindex="-1">行為變更（需注意） <a class="header-anchor" href="#行為變更-需注意" aria-label="Permalink to &quot;行為變更（需注意）&quot;">​</a></h3><p><strong><code>!</code> bash 指令現在會觸發 Claude 自動回應輸出</strong>（原本只是把輸出放進 context，不主動回應）。要恢復舊行為：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// settings.json</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;respondToBashCommands&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="claude-code-max-retries-上限變更" tabindex="-1"><code>CLAUDE_CODE_MAX_RETRIES</code> 上限變更 <a class="header-anchor" href="#claude-code-max-retries-上限變更" aria-label="Permalink to &quot;`CLAUDE_CODE_MAX_RETRIES` 上限變更&quot;">​</a></h3><p>本版將 <code>CLAUDE_CODE_MAX_RETRIES</code> 上限訂為 <strong>15</strong>（無人值守 session 改用 <code>CLAUDE_CODE_RETRY_WATCHDOG</code>）。<strong>此上限已在 v2.1.199 針對非容量類 transient error 再次放寬</strong>，見下方。</p><h3 id="安全性修復" tabindex="-1">安全性修復 <a class="header-anchor" href="#安全性修復" aria-label="Permalink to &quot;安全性修復&quot;">​</a></h3><ul><li><code>Agent(type)</code> deny 規則 / <code>Agent(x,y)</code> allowed-types 未被強制執行的 bug（<strong>安全相關</strong>）</li></ul><h3 id="其他修復" tabindex="-1">其他修復 <a class="header-anchor" href="#其他修復" aria-label="Permalink to &quot;其他修復&quot;">​</a></h3><ul><li>睡眠恢復後串流「Content block not found」/ JSON parse 錯誤</li><li>Subagent transcript 捲動殘影、背景任務預覽顯示原始工具名稱</li><li>Chrome tab-group 隔離、背景 recap 訊息重複</li><li>主 turn 結束後背景 agent 仍在跑時 Esc/Ctrl+C 失去回應</li><li>Permission prompt 選項編號錯位、<code>~~刪除線~~</code> 字面 tilde 未渲染</li><li><code>--tools</code> flag-gate race condition（冷啟動）</li><li>Agent teams <code>--effort</code> 繼承問題（tmux/pane teammates）</li><li>Workflow <code>agent({schema})</code> 無限迴圈（現在 5 次嘗試後中止）</li></ul><h3 id="改善" tabindex="-1">改善 <a class="header-anchor" href="#改善" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><code>claude mcp get</code>/<code>remove</code> 拼字建議、MEMORY.md compaction 提醒</li><li>Skill frontmatter key 大小寫容錯（<code>display-name</code>/<code>default-enabled</code>/<code>fallback</code>/<code>metadata.*</code> 接受 kebab/snake/camelCase）</li><li><code>SKILL.md</code> YAML 格式錯誤時改為載入 body（空 metadata），不再靜默失敗</li></ul><hr><h2 id="v2-1-187-2026-06-23-feature-dense-security" tabindex="-1">v2.1.187（2026-06-23，feature-dense + security） <a class="header-anchor" href="#v2-1-187-2026-06-23-feature-dense-security" aria-label="Permalink to &quot;v2.1.187（2026-06-23，feature-dense + security）&quot;">​</a></h2><h3 id="sandbox-credentials-設定" tabindex="-1"><code>sandbox.credentials</code> 設定 <a class="header-anchor" href="#sandbox-credentials-設定" aria-label="Permalink to &quot;`sandbox.credentials` 設定&quot;">​</a></h3><p>新增設定，封鎖 sandboxed 指令讀取憑證檔案 / secret 環境變數。</p><h3 id="其他新增-1" tabindex="-1">其他新增 <a class="header-anchor" href="#其他新增-1" aria-label="Permalink to &quot;其他新增&quot;">​</a></h3><ul><li>Org 層級 model 限制反映在 model picker、<code>--model</code>、<code>/model</code>、<code>ANTHROPIC_MODEL</code>（顯示「restricted by your organization&#39;s settings」）</li><li>Fullscreen 下 select menu（permission prompt / <code>/model</code> / <code>/config</code>）支援滑鼠點擊</li></ul><h3 id="修復" tabindex="-1">修復 <a class="header-anchor" href="#修復" aria-label="Permalink to &quot;修復&quot;">​</a></h3><ul><li><code>--resume</code> 在 <code>-p</code> 執行未產生 model turn 時報「No conversation found」</li><li><code>--json-schema</code> / workflow <code>agent({schema})</code> 無限重呼叫 bug</li><li>Remote MCP tool call 無限期 hang——現在 <strong>5 分鐘後自動 abort</strong>，可用 <code>CLAUDE_CODE_MCP_TOOL_IDLE_TIMEOUT</code> 覆寫</li><li>Remote session 啟動延遲 +2.7s 迴歸</li><li>貼上韓文/CJK 亂碼</li><li><code>/update</code> 於 Remote Control 下卡住</li><li>背景任務永久卡在「working」狀態</li><li>Subagent 深度追蹤（resume/fork 場景）、殘留 agent worktree 註冊</li></ul><h3 id="改善-1" tabindex="-1">改善 <a class="header-anchor" href="#改善-1" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li><code>/install-github-app</code>：GitHub App 安裝改為選用，可跳過 workflow/secret 步驟</li><li><code>/btw</code> 方向鍵導覽、<code>/plugin</code> 顯示未使用的 plugin</li></ul><hr><h2 id="v2-1-190-v2-1-191-2026-06-24" tabindex="-1">v2.1.190 / v2.1.191（2026-06-24） <a class="header-anchor" href="#v2-1-190-v2-1-191-2026-06-24" aria-label="Permalink to &quot;v2.1.190 / v2.1.191（2026-06-24）&quot;">​</a></h2><h3 id="rewind-支援跨越-clear-恢復" tabindex="-1"><code>/rewind</code> 支援跨越 <code>/clear</code> 恢復 <a class="header-anchor" href="#rewind-支援跨越-clear-恢復" aria-label="Permalink to &quot;`/rewind` 支援跨越 `/clear` 恢復&quot;">​</a></h3><p><strong><code>/rewind</code> 現在可以恢復到 <code>/clear</code> 執行之前的對話</strong>——先前 <code>/clear</code> 是不可逆的邊界，此版打通後可救回誤 <code>/clear</code> 的 session。</p><h3 id="效能" tabindex="-1">效能 <a class="header-anchor" href="#效能" aria-label="Permalink to &quot;效能&quot;">​</a></h3><ul><li><strong>串流時 CPU 使用量降低約 37%</strong>（100ms 文字更新合併批次處理）</li><li>長 session 記憶體成長速度降低（終端輸出快取優化）</li></ul><h3 id="修復-1" tabindex="-1">修復 <a class="header-anchor" href="#修復-1" aria-label="Permalink to &quot;修復&quot;">​</a></h3><ul><li>串流時捲動跳動</li><li>背景 agent 在 stop 後「復活」的 bug（現已<strong>永久修復</strong>）</li><li><code>/voice</code> 組織政策提示訊息</li><li>Windows Terminal 下 <code>/login</code> URL 截斷</li><li>Ghostty ssh/tmux 下 Cmd+click</li><li><code>claude agents</code> 誤把內建 slash command 當成 prompt 文字送出</li><li>圖片路徑洩漏（改用 <code>[Image #N]</code> placeholder）</li><li>逗號分隔的 hook matcher（如 <code>&quot;Bash,PowerShell&quot;</code>）完全不觸發的 bug</li><li><code>/permissions</code> Recently-denied 核可狀態未持久化</li><li>Managed settings <code>forceRemoteSettingsRefresh</code>（MDM/檔案政策）+ <code>Cache-Control: no-cache</code></li></ul><h3 id="改善-2" tabindex="-1">改善 <a class="header-anchor" href="#改善-2" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>Sandbox 網路權限對話記住當次 session 已核可的 host</li><li>MCP capability discovery（<code>tools/list</code>/<code>prompts/list</code>/<code>resources/list</code>）針對 transient error 重試</li><li>MCP OAuth 重試 + headless 貼 URL 流程</li></ul><hr><h2 id="v2-1-193-2026-06-25-feature-dense" tabindex="-1">v2.1.193（2026-06-25，feature-dense） <a class="header-anchor" href="#v2-1-193-2026-06-25-feature-dense" aria-label="Permalink to &quot;v2.1.193（2026-06-25，feature-dense）&quot;">​</a></h2><h3 id="automode-classifyallshell" tabindex="-1"><code>autoMode.classifyAllShell</code> <a class="header-anchor" href="#automode-classifyallshell" aria-label="Permalink to &quot;`autoMode.classifyAllShell`&quot;">​</a></h3><p>新設定：讓 auto mode 分類器處理<strong>所有</strong> Bash/PowerShell 指令，不再只針對「任意程式碼執行」樣式的指令做分類。</p><h3 id="opentelemetry-新事件-claude-code-assistant-response" tabindex="-1">OpenTelemetry 新事件：<code>claude_code.assistant_response</code> <a class="header-anchor" href="#opentelemetry-新事件-claude-code-assistant-response" aria-label="Permalink to &quot;OpenTelemetry 新事件：`claude_code.assistant_response`&quot;">​</a></h3><p>新增記錄模型回應文字的 OTel log event。</p><p>⚠️ <strong>需注意的行為變更</strong>：</p><ul><li>預設 <strong>redacted</strong>，需 <code>OTEL_LOG_ASSISTANT_RESPONSES=1</code> 才會記錄</li><li>若未設定，<strong>跟隨 <code>OTEL_LOG_USER_PROMPTS</code> 的值</strong>——已在記錄 user prompts 的部署，升級後會<strong>開始一併記錄 assistant response 內容</strong></li><li>想維持「只記 prompt、不記 response」需明確設 <code>OTEL_LOG_ASSISTANT_RESPONSES=0</code></li></ul><h3 id="其他新增-2" tabindex="-1">其他新增 <a class="header-anchor" href="#其他新增-2" aria-label="Permalink to &quot;其他新增&quot;">​</a></h3><ul><li>Bash mode（<code>!</code>）即時檔案路徑自動完成</li><li>MCP server 需要認證時的啟動提示，導向 <code>/mcp</code></li><li>閒置背景 shell 指令的自動記憶體壓力回收，停用旗標 <code>CLAUDE_CODE_DISABLE_BG_SHELL_PRESSURE_REAP=1</code></li></ul><h3 id="修復-2" tabindex="-1">修復 <a class="header-anchor" href="#修復-2" aria-label="Permalink to &quot;修復&quot;">​</a></h3><ul><li>登入後 <code>/model</code> UI 顯示過期資訊</li><li>Backgrounding 誤報「N background tasks would be abandoned」而取消</li><li>自動更新後 pinned agent 重新詢問</li><li>幽靈「general-purpose (resumed)」subagent、agent panel 隱藏 sibling 的問題</li></ul><hr><h2 id="v2-1-195-2026-06-26-minor" tabindex="-1">v2.1.195（2026-06-26，minor） <a class="header-anchor" href="#v2-1-195-2026-06-26-minor" aria-label="Permalink to &quot;v2.1.195（2026-06-26，minor）&quot;">​</a></h2><ul><li>新增 <strong><code>CLAUDE_CODE_DISABLE_MOUSE_CLICKS</code></strong> 環境變數——停用 fullscreen 模式下滑鼠點擊/拖曳/hover，但保留滾輪</li><li>修復 hook matcher 對含連字號 identifier（如 <code>code-reviewer</code>、<code>mcp__brave-search</code>）誤判為子字串匹配的 bug——現改<strong>精確匹配</strong>；要匹配某 hyphenated MCP server 底下所有工具需寫 <code>mcp__brave-search__.*</code></li><li>修復語音聽寫問題（macOS 靜音錄音、無空格語言如日文/中文/泰文自動送出失敗）</li><li>修復僅由專案 <code>.claude/settings.json</code> 啟用的外部 plugin 未要求安裝同意的問題</li><li>修復 <code>/plugin</code> 在 <code>plugin.json</code> name 與 marketplace entry name 不同時的 Enable/Disable 行為</li></ul><hr><h2 id="v2-1-196-2026-06-29-feature-security" tabindex="-1">v2.1.196（2026-06-29，feature + security） <a class="header-anchor" href="#v2-1-196-2026-06-29-feature-security" aria-label="Permalink to &quot;v2.1.196（2026-06-29，feature + security）&quot;">​</a></h2><h3 id="org-層級預設模型" tabindex="-1">Org 層級預設模型 <a class="header-anchor" href="#org-層級預設模型" aria-label="Permalink to &quot;Org 層級預設模型&quot;">​</a></h3><p>管理員可在 org console 設定組織預設模型；使用者未自選時 <code>/model</code> 顯示「Org default」（或「Role default」）。</p><h3 id="安全修復" tabindex="-1">安全修復 <a class="header-anchor" href="#安全修復" aria-label="Permalink to &quot;安全修復&quot;">​</a></h3><p><code>claude mcp list</code>/<code>get</code> <strong>不再自動 spawn</strong> 由 untrusted workspace 中已提交的 <code>.claude/settings.json</code> 自我核准的 <code>.mcp.json</code> server——改顯示 <code>⏸ Pending approval</code>。</p><h3 id="其他新增-3" tabindex="-1">其他新增 <a class="header-anchor" href="#其他新增-3" aria-label="Permalink to &quot;其他新增&quot;">​</a></h3><ul><li>啟動時顯示可讀的預設 session 名稱</li><li>聊天中的檔案附件可點擊（Cmd/Ctrl-click 在 Finder/Explorer 中顯示）</li></ul><h3 id="串流閒置監控預設開啟" tabindex="-1">串流閒置監控預設開啟 <a class="header-anchor" href="#串流閒置監控預設開啟" aria-label="Permalink to &quot;串流閒置監控預設開啟&quot;">​</a></h3><p><strong>Streaming idle watchdog 現在對所有 provider 預設開啟</strong>：串流 <strong>5 分鐘</strong>無任何事件即 abort/retry；停用旗標 <code>CLAUDE_ENABLE_STREAM_WATCHDOG=0</code>。</p><h3 id="其他修復-1" tabindex="-1">其他修復 <a class="header-anchor" href="#其他修復-1" aria-label="Permalink to &quot;其他修復&quot;">​</a></h3><ul><li>喚醒背景任務時誤刪對話並重跑原始 prompt（transcript probe 誤判）</li><li>Rate-limit 警告閃爍/重複計數、重複 recap 行（StructuredOutput schema 被拒）</li><li>PowerShell 下 <code>git diff</code>/<code>git grep</code>/<code>egrep</code>/<code>fgrep</code> 誤報 exit-1 失敗</li><li><code>claude agents</code> panel（focus 卡住、subagent type 遺失、狀態顯示錯誤）</li><li><code>claude agents --dangerously-skip-permissions</code> fallback bug</li><li>MCP OAuth <code>scopes_supported</code> 導致 GitLab self-hosted <code>invalid_scope</code> 錯誤</li><li>Bedrock 下 <code>/context</code> 顯示 0 tokens</li><li><code>/deep-research</code> 誤報 verifier 失敗</li><li>Plugin 依賴版本鎖定、語音聽寫吞掉空格</li></ul><h3 id="改善-3" tabindex="-1">改善 <a class="header-anchor" href="#改善-3" aria-label="Permalink to &quot;改善&quot;">​</a></h3><ul><li>背景 session 可靠性（撐過 stop/restart/update，含 Windows shell handoff）</li><li>背景 agent 在 daemon 重啟後自動恢復</li><li><strong><code>/code-review</code> workflow 將五個清理型 finder 合併為一個，token 減少約 25%</strong></li><li>Remote Control 在 <code>ANTHROPIC_BASE_URL</code> 指向非 Anthropic host 時自動停用（比照既有 <code>CLAUDE_CODE_USE_BEDROCK</code>/<code>_VERTEX</code>/<code>_FOUNDRY</code> 行為）</li><li>從前景 session 開啟 agents view 現在只需按一次 <code>←</code>（原本要兩次）</li></ul><hr><h2 id="v2-1-197-2026-06-30-major-—-新模型" tabindex="-1">v2.1.197（2026-06-30，MAJOR — 新模型） <a class="header-anchor" href="#v2-1-197-2026-06-30-major-—-新模型" aria-label="Permalink to &quot;v2.1.197（2026-06-30，MAJOR — 新模型）&quot;">​</a></h2><blockquote><p><strong>Claude Sonnet 5 發布</strong>，成為 Claude Code 預設模型，原生 <strong>1M-token context window</strong>，促銷定價 <strong>$2/$10 per Mtok</strong>（至 2026-08-31）。詳見專篇 <code>41-claude-sonnet-5.md</code>。</p></blockquote><hr><h2 id="v2-1-198-2026-07-01-major-—-多項重大功能" tabindex="-1">v2.1.198（2026-07-01，MAJOR — 多項重大功能） <a class="header-anchor" href="#v2-1-198-2026-07-01-major-—-多項重大功能" aria-label="Permalink to &quot;v2.1.198（2026-07-01，MAJOR — 多項重大功能）&quot;">​</a></h2><h3 id="subagent-預設背景執行" tabindex="-1">Subagent 預設背景執行 <a class="header-anchor" href="#subagent-預設背景執行" aria-label="Permalink to &quot;Subagent 預設背景執行&quot;">​</a></h3><p>Subagent（含 sub-sub-agent）<strong>現在預設在背景執行</strong>（先前為漸進式 rollout，本版全面預設開啟）。</p><h3 id="claude-in-chrome-正式-ga" tabindex="-1">Claude in Chrome 正式 GA <a class="header-anchor" href="#claude-in-chrome-正式-ga" aria-label="Permalink to &quot;Claude in Chrome 正式 GA&quot;">​</a></h3><p>瀏覽器操作能力（Computer Use 的瀏覽器變體）正式脫離 beta。</p><h3 id="背景-agent-通知" tabindex="-1">背景 agent 通知 <a class="header-anchor" href="#背景-agent-通知" aria-label="Permalink to &quot;背景 agent 通知&quot;">​</a></h3><p><code>claude agents</code> 新增背景 agent 通知，觸發 <code>Notification</code> hook，事件類型 <code>agent_needs_input</code> / <code>agent_completed</code>。</p><h3 id="dataviz-skill" tabindex="-1"><code>/dataviz</code> skill <a class="header-anchor" href="#dataviz-skill" aria-label="Permalink to &quot;`/dataviz` skill&quot;">​</a></h3><p>新增官方 skill，提供圖表/dashboard 設計指引 + 可執行的色票驗證工具。</p><h3 id="gateway-新增-aws-上游-provider" tabindex="-1">Gateway：新增 AWS 上游 provider <a class="header-anchor" href="#gateway-新增-aws-上游-provider" aria-label="Permalink to &quot;Gateway：新增 AWS 上游 provider&quot;">​</a></h3><p>新增 <strong>Claude Platform on AWS</strong>（<code>anthropicAws</code>）作為 gateway 上游 provider；model-not-found 回應現在會推進 failover chain。</p><h3 id="背景-agent-自動-commit-push-開-draft-pr" tabindex="-1">背景 agent 自動 commit + push + 開 draft PR <a class="header-anchor" href="#背景-agent-自動-commit-push-開-draft-pr" aria-label="Permalink to &quot;背景 agent 自動 commit + push + 開 draft PR&quot;">​</a></h3><p><code>claude agents</code> 產生的背景 agent 完成 worktree 內的程式碼工作後，<strong>自動 commit、push、開 draft PR</strong>，不再停下來詢問。</p><h3 id="explore-agent-繼承主-session-模型" tabindex="-1">Explore agent 繼承主 session 模型 <a class="header-anchor" href="#explore-agent-繼承主-session-模型" aria-label="Permalink to &quot;Explore agent 繼承主 session 模型&quot;">​</a></h3><p>內建 Explore agent 現在繼承主 session 的模型（上限 opus），不再固定跑 haiku。</p><h3 id="subagent-context-compaction-繼承-extended-thinking-設定" tabindex="-1">Subagent / context compaction 繼承 extended thinking 設定 <a class="header-anchor" href="#subagent-context-compaction-繼承-extended-thinking-設定" aria-label="Permalink to &quot;Subagent / context compaction 繼承 extended thinking 設定&quot;">​</a></h3><h3 id="移除-agents-wizard" tabindex="-1">移除 <code>/agents</code> wizard <a class="header-anchor" href="#移除-agents-wizard" aria-label="Permalink to &quot;移除 `/agents` wizard&quot;">​</a></h3><p>改為直接請 Claude 建立/管理 subagent，或直接編輯 <code>.claude/agents/</code>。</p><h3 id="修復-3" tabindex="-1">修復 <a class="header-anchor" href="#修復-3" aria-label="Permalink to &quot;修復&quot;">​</a></h3><ul><li>短暫網路中斷（ECONNRESET）串流中途自動重試</li><li>重複 sandboxed 網路 host access 觸發過多背景分類器請求</li><li>Web/desktop/VS Code 任務面板背景任務卡「Running」</li><li>Agent teams：teammate 因 API error 死亡時正確回報「failed」；發訊息可喚醒卡住的 teammate</li><li><code>/diff</code> panel 分支切換未刷新</li><li>Fullscreen 下 Markdown 表格溢出</li><li>Claude Platform on AWS/Mantle session 因 STS 過期而 dead-end——<code>awsAuthRefresh</code> 現在自動執行</li><li>macOS Local Network entitlements 修復「no route to host」</li><li><code>/desktop</code> 離開 worktree 後「Cannot determine working directory」</li><li>背景 agent macOS 上每約 52 秒「Reconnecting…」閃爍</li><li><code>claude attach &lt;id&gt;</code> 中按 <code>←</code> 誤退出到 shell</li><li><code>claude --bg</code> + <code>--print</code>/<code>-p</code> 衝突現在提前拒絕</li><li>Workflow progress view 遺失最早的 agent</li><li><code>.claude/rules/</code> 條件式規則透過 symlink 路徑不載入</li><li><code>/branch</code> 預設 fork 名稱改從第一則真實 prompt 取得（原本用 compaction summary）</li></ul><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><ul><li>Focus mode：一個 turn 內的 subagent 出現在活動摘要中，通知折疊為單一計數</li><li>Syntax highlighting 升級至 highlight.js 11</li><li><strong>安全相關</strong>：subagent 將 launcher 訊息視為任務指示，<strong>永不</strong>視為 user approval</li></ul><hr><h2 id="v2-1-199-2026-07-02-feature-reliability" tabindex="-1">v2.1.199（2026-07-02，feature + reliability） <a class="header-anchor" href="#v2-1-199-2026-07-02-feature-reliability" aria-label="Permalink to &quot;v2.1.199（2026-07-02，feature + reliability）&quot;">​</a></h2><h3 id="skill-疊加呼叫支援多個前綴-skill" tabindex="-1">Skill 疊加呼叫支援多個前綴 skill <a class="header-anchor" href="#skill-疊加呼叫支援多個前綴-skill" aria-label="Permalink to &quot;Skill 疊加呼叫支援多個前綴 skill&quot;">​</a></h3><p><code>/skill-a /skill-b do XYZ</code> 現在載入<strong>所有前綴 skill（最多 5 個）</strong>，不再只載入第一個。</p><h3 id="其他新增-4" tabindex="-1">其他新增 <a class="header-anchor" href="#其他新增-4" aria-label="Permalink to &quot;其他新增&quot;">​</a></h3><ul><li>SSL 憑證錯誤（TLS-inspecting proxy、缺 <code>NODE_EXTRA_CA_CERTS</code>、過期憑證）現在立即失敗並給修復提示，不再浪費重試次數</li></ul><h3 id="可靠性修復" tabindex="-1">可靠性修復 <a class="header-anchor" href="#可靠性修復" aria-label="Permalink to &quot;可靠性修復&quot;">​</a></h3><ul><li>串流過程中 mid-stream overloaded/server error 現在保留部分輸出 + 顯示未完成提示</li><li>Subagent 因 rate-limit/server error 中斷時<strong>回傳部分工作給 parent</strong>，不再靜默失敗</li><li>Subagent 把 API 錯誤（如額度用盡）誤報為「成功」的 bug——現在正確回報為錯誤</li><li>Linux 背景 agent daemon 在非乾淨關閉後每約 50 秒自我終止迴圈</li><li>macOS SSH 冷啟動失敗（&quot;Could not switch to audit session&quot; — v2.1.196 的迴歸）</li><li><code>claude stop</code> 被競速的背景 agent respawn 靜默復原</li><li>背景任務進度指示器在長指令執行中卡住</li><li>低記憶體機器顯示通用錯誤而非記憶體提示</li><li>Remote session 在 agent view 中 Working/Idle 狀態閃爍</li><li>閒置 subagent 從 agent panel 消失（現折疊為可展開摘要列）</li><li>查看 subagent 時按 <code>/model</code>/<code>/fast</code> 誤開 lead 的 picker</li><li><code>SessionStart</code>/<code>Setup</code>/<code>SubagentStart</code> hook 在 exit code 2 時隱藏 stderr</li><li><code>SendMessage</code> 在 agent 名稱重複使用時誤路由</li></ul><h3 id="claude-code-retry-watchdog-重試上限放寬" tabindex="-1"><code>CLAUDE_CODE_RETRY_WATCHDOG</code> 重試上限放寬 <a class="header-anchor" href="#claude-code-retry-watchdog-重試上限放寬" aria-label="Permalink to &quot;`CLAUDE_CODE_RETRY_WATCHDOG` 重試上限放寬&quot;">​</a></h3><p><strong>非容量類 transient error 的預設重試次數提高到 300</strong>，並解除 <code>CLAUDE_CODE_MAX_RETRIES</code> 原本的 <strong>15 上限</strong>（v2.1.186 訂下的上限）。</p><h3 id="其他改善" tabindex="-1">其他改善 <a class="header-anchor" href="#其他改善" aria-label="Permalink to &quot;其他改善&quot;">​</a></h3><ul><li>訂閱用戶的 transient 429 rate-limit 現在自動重試 + backoff</li><li><code>claude agents</code> 中 PR 連結顯示為簡潔的 <code>#N</code></li></ul><hr><h2 id="v2-1-200-2026-07-03-行為變更-大量修復" tabindex="-1">v2.1.200（2026-07-03，行為變更 + 大量修復） <a class="header-anchor" href="#v2-1-200-2026-07-03-行為變更-大量修復" aria-label="Permalink to &quot;v2.1.200（2026-07-03，行為變更 + 大量修復）&quot;">​</a></h2><h3 id="預設-permission-mode-改為-manual" tabindex="-1">預設 permission mode 改為 &quot;Manual&quot; <a class="header-anchor" href="#預設-permission-mode-改為-manual" aria-label="Permalink to &quot;預設 permission mode 改為 &quot;Manual&quot;&quot;">​</a></h3><p>CLI、<code>--help</code>、VS Code、JetBrains 的<strong>預設 permission mode 從先前預設改為 &quot;Manual&quot;</strong>；<code>--permission-mode manual</code> 與 <code>&quot;defaultMode&quot;: &quot;manual&quot;</code> 與既有 <code>default</code> 同時接受。</p><p><strong>影響</strong>：升級後首次啟動若未明確設定 permission mode，行為會更保守（更多工具呼叫需人工核可）——習慣舊預設值的自動化腳本/CI 需明確指定 permission mode。</p><h3 id="askuserquestion-不再自動繼續" tabindex="-1"><code>AskUserQuestion</code> 不再自動繼續 <a class="header-anchor" href="#askuserquestion-不再自動繼續" aria-label="Permalink to &quot;`AskUserQuestion` 不再自動繼續&quot;">​</a></h3><p><code>AskUserQuestion</code> 對話框現在<strong>預設不再自動繼續</strong>；需透過 <code>/config</code> 選擇加入 idle timeout。</p><h3 id="大量可靠性修復-背景-agent-daemon" tabindex="-1">大量可靠性修復（背景 agent / daemon） <a class="header-anchor" href="#大量可靠性修復-背景-agent-daemon" aria-label="Permalink to &quot;大量可靠性修復（背景 agent / daemon）&quot;">​</a></h3><ul><li><code>.claude.json</code> 中 <code>disabledMcpServers</code>/<code>enabledMcpServers</code> 非陣列時啟動崩潰</li><li>背景 session 在睡眠/喚醒後或重開 stalled session 時靜默中途停止</li><li>背景 session 在 Esc 取消的 stall respawn 後重跑該 turn</li><li>背景 agent crash 後從未重啟 + stale <code>daemon.lock</code> PID 重用問題</li><li>背景 agent daemon handover 強化（透過內嵌 build timestamp 判斷新舊）</li><li>背景 agent roster 損毀問題（孤兒清理、欄位保留、socket auth token 剝離）</li></ul><h3 id="其他修復-2" tabindex="-1">其他修復 <a class="header-anchor" href="#其他修復-2" aria-label="Permalink to &quot;其他修復&quot;">​</a></h3><ul><li>Subagent 在任何文字輸出前被 rate limit 截斷，現在乾淨失敗而非回傳空結果</li><li>背景 agent 輸出的控制位元組洩漏到終端</li><li><code>claude agents --plugin-dir &lt;dir&gt;</code> flag 順序 bug</li><li>專案範圍 plugin 無法從 git worktree 載入</li><li><code>/mcp</code> server 列表畫面朗讀器 focus 追蹤</li><li>語音聽寫在無聲錄音時誤報「Voice connection failed」</li><li>tmux 3.4+ 下渲染閃爍（透過同步終端輸出修復）</li><li>朗讀器輸出改善（隱藏裝飾性字符、transcript 標籤、表格朗讀）</li><li>安裝腳本現在會解釋安裝過程中的 OOM-kill</li></ul><hr><h2 id="v2-1-201-2026-07-03-minor-internal" tabindex="-1">v2.1.201（2026-07-03，minor/internal） <a class="header-anchor" href="#v2-1-201-2026-07-03-minor-internal" aria-label="Permalink to &quot;v2.1.201（2026-07-03，minor/internal）&quot;">​</a></h2><p>Claude Sonnet 5 session 不再使用對話中段的 system role 承載 harness 提醒。</p><hr><h2 id="功能對照索引" tabindex="-1">功能對照索引 <a class="header-anchor" href="#功能對照索引" aria-label="Permalink to &quot;功能對照索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>版本</th><th>日期</th></tr></thead><tbody><tr><td>串流中斷提示延長至 20s</td><td>v2.1.185</td><td>2026-06-20</td></tr><tr><td><code>claude mcp login</code>/<code>logout</code> CLI 認證</td><td>v2.1.186</td><td>2026-06-22</td></tr><tr><td><code>!</code> bash 自動回應行為變更（<code>respondToBashCommands</code>）</td><td>v2.1.186</td><td>2026-06-22</td></tr><tr><td><code>CLAUDE_CODE_MAX_RETRIES</code> 上限訂為 15</td><td>v2.1.186</td><td>2026-06-22</td></tr><tr><td><code>sandbox.credentials</code> 設定</td><td>v2.1.187</td><td>2026-06-23</td></tr><tr><td>Org 層級 model 限制反映於 model picker</td><td>v2.1.187</td><td>2026-06-23</td></tr><tr><td>MCP tool call 5 分鐘逾時（<code>CLAUDE_CODE_MCP_TOOL_IDLE_TIMEOUT</code>）</td><td>v2.1.187</td><td>2026-06-23</td></tr><tr><td><code>/rewind</code> 支援跨越 <code>/clear</code> 恢復</td><td>v2.1.191</td><td>2026-06-24</td></tr><tr><td>串流 CPU 使用量降低 ~37%</td><td>v2.1.191</td><td>2026-06-24</td></tr><tr><td><code>autoMode.classifyAllShell</code></td><td>v2.1.193</td><td>2026-06-25</td></tr><tr><td><code>claude_code.assistant_response</code> OTel 事件</td><td>v2.1.193</td><td>2026-06-25</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_BG_SHELL_PRESSURE_REAP</code></td><td>v2.1.193</td><td>2026-06-25</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_MOUSE_CLICKS</code></td><td>v2.1.195</td><td>2026-06-26</td></tr><tr><td>Hook matcher 連字號精確匹配修復</td><td>v2.1.195</td><td>2026-06-26</td></tr><tr><td>Org 層級預設模型</td><td>v2.1.196</td><td>2026-06-29</td></tr><tr><td><code>.mcp.json</code> 自我核准安全修復</td><td>v2.1.196</td><td>2026-06-29</td></tr><tr><td>Streaming idle watchdog 預設開啟（5 分鐘）</td><td>v2.1.196</td><td>2026-06-29</td></tr><tr><td><code>/code-review</code> finder 合併，token -25%</td><td>v2.1.196</td><td>2026-06-29</td></tr><tr><td><strong>Claude Sonnet 5 發布</strong>（1M context，$2/$10 促銷）</td><td>v2.1.197</td><td>2026-06-30</td></tr><tr><td>Subagent 預設背景執行</td><td>v2.1.198</td><td>2026-07-01</td></tr><tr><td>Claude in Chrome GA</td><td>v2.1.198</td><td>2026-07-01</td></tr><tr><td><code>/dataviz</code> skill</td><td>v2.1.198</td><td>2026-07-01</td></tr><tr><td>Claude Platform on AWS gateway provider</td><td>v2.1.198</td><td>2026-07-01</td></tr><tr><td>背景 agent 自動 commit+push+draft PR</td><td>v2.1.198</td><td>2026-07-01</td></tr><tr><td>移除 <code>/agents</code> wizard</td><td>v2.1.198</td><td>2026-07-01</td></tr><tr><td>Skill 疊加呼叫支援最多 5 個前綴 skill</td><td>v2.1.199</td><td>2026-07-02</td></tr><tr><td>Subagent 部分結果回傳（rate-limit 中斷）</td><td>v2.1.199</td><td>2026-07-02</td></tr><tr><td><code>CLAUDE_CODE_RETRY_WATCHDOG</code> 上限放寬至 300（解除 15 上限）</td><td>v2.1.199</td><td>2026-07-02</td></tr><tr><td>預設 permission mode 改為 &quot;Manual&quot;</td><td>v2.1.200</td><td>2026-07-03</td></tr><tr><td><code>AskUserQuestion</code> 不再自動繼續</td><td>v2.1.200</td><td>2026-07-03</td></tr><tr><td>Sonnet 5 移除 mid-conversation system role 提醒</td><td>v2.1.201</td><td>2026-07-03</td></tr></tbody></table><hr><h2 id="需要立即檢視的變更-升級後行動項" tabindex="-1">需要立即檢視的變更（升級後行動項） <a class="header-anchor" href="#需要立即檢視的變更-升級後行動項" aria-label="Permalink to &quot;需要立即檢視的變更（升級後行動項）&quot;">​</a></h2><ol><li><strong>Permission mode 預設改為 Manual</strong>（v2.1.200）——CI/自動化腳本若依賴舊預設值，需明確指定 <code>--permission-mode</code> 或 <code>&quot;defaultMode&quot;</code>。</li><li><strong><code>!</code> bash 自動回應</strong>（v2.1.186）——若 workflow 依賴「純輸出、不觸發回應」的舊行為，需設 <code>&quot;respondToBashCommands&quot;: false</code>。</li><li><strong><code>OTEL_LOG_ASSISTANT_RESPONSES</code> 跟隨 <code>OTEL_LOG_USER_PROMPTS</code></strong>（v2.1.193）——已在記錄 prompt 的 OTel 部署，升級後會<strong>開始一併記錄 response 內容</strong>，涉合規/隱私需明確設 <code>=0</code> 關閉。</li><li><strong>Subagent 預設背景執行 + 自動 commit/push/開 draft PR</strong>（v2.1.198）——委派拓樸與 sub-agent 產出「回主 context 前先審查」的既有假設需重新核對（本 workspace <code>subagent-strategy.md</code> 的「產出者不驗收自己的產出」原則仍適用，但背景 agent 現在會<strong>先開 PR 才被看到</strong>，稽核時機需提前到 PR review）。</li><li><strong><code>Agent(type)</code> deny 規則此前未強制執行</strong>（v2.1.186 修復前）——已設定該類 deny rule 的環境應確認修復生效（升級到 v2.1.186+）。</li></ol><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><a href="./41-claude-sonnet-5">41-claude-sonnet-5.md</a> — Claude Sonnet 5 模型專篇</li><li><a href="./12-permissions">12-permissions.md</a> — Permission 系統架構（v2.1.200 預設值變更的背景知識）</li><li><a href="./40-w25-features">40-w25-features.md</a> — 前一批（W25）功能</li><li><a href="./32-dynamic-workflows">32-dynamic-workflows.md</a> — Dynamic Workflows（<code>agent({schema})</code> 相關修復見本檔）</li></ul>',134)])])}const p=a(i,[["render",l]]);export{g as __pageData,p as default};
